package com.firemaking;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class FiremakingOverlay extends OverlayPanel
{
	static final String RESET = "Reset";

	private final FiremakingPlugin plugin;
	private final FiremakingConfig config;

	@Inject
	private FiremakingOverlay(FiremakingPlugin plugin, FiremakingConfig config)
	{
		super(plugin);
		setPosition(OverlayPosition.TOP_LEFT);
		this.plugin = plugin;
		this.config = config;
		getMenuEntries().add(new OverlayMenuEntry(RUNELITE_OVERLAY_CONFIG, "Configure", "Firemaking overlay"));
		getMenuEntries().add(new OverlayMenuEntry(RUNELITE_OVERLAY, RESET, "Firemaking overlay"));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		FiremakingSession session = plugin.getSession();

		if (session == null || !config.showFiremakingStats())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Firemaking")
			.color(Color.CYAN)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Fires lit:")
			.right(Integer.toString(session.getFiresLit()))
			.build());

		int xpGained = session.getXpGained();
		if (xpGained > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("XP gained:")
				.right(Integer.toString(xpGained))
				.build());
		}

		int xpPerHr = session.getXpPerHour();
		if (xpPerHr != -1)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("XP/hr:")
				.right(Integer.toString(xpPerHr))
				.build());
		}

		return super.render(graphics);
	}
}

package com.firemaking;

import java.time.Duration;
import java.time.Instant;
import lombok.Getter;
import lombok.Setter;

@Getter
@Setter
public class FiremakingSession
{
	private static final int MINIMUM_FIRES_FOR_RATE = 3;

	private Instant startTime;
	private Instant lastActivity;
	private int firesLit;
	private int startXp;
	private int lastXp;
	private int cachedXpPerHour = -1;
	private Instant lastXpPerHourCalc = Instant.EPOCH;

	FiremakingSession()
	{
		startTime = Instant.now();
		lastActivity = Instant.now();
		firesLit = 0;
		startXp = -1;
		lastXp = -1;
	}

	void incrementFiresLit()
	{
		firesLit++;
		lastActivity = Instant.now();
	}

	/**
	 * Returns XP gained since session start, or 0 if XP hasn't been tracked yet.
	 */
	int getXpGained()
	{
		if (startXp == -1 || lastXp == -1)
		{
			return 0;
		}

		return lastXp - startXp;
	}

	/**
	 * Returns XP per hour, or -1 if not enough data.
	 * Cached and recalculated at most every 5 seconds to avoid jittery updates.
	 */
	int getXpPerHour()
	{
		Instant now = Instant.now();
		if (cachedXpPerHour != -1 && Duration.between(lastXpPerHourCalc, now).getSeconds() < 5)
		{
			return cachedXpPerHour;
		}

		int xpGained = getXpGained();
		if (xpGained <= 0 || firesLit < MINIMUM_FIRES_FOR_RATE)
		{
			return -1;
		}

		Duration elapsed = Duration.between(startTime, now);
		long seconds = elapsed.getSeconds();
		if (seconds == 0)
		{
			return -1;
		}

		cachedXpPerHour = (int) (xpGained * 3600.0 / seconds);
		lastXpPerHourCalc = now;
		return cachedXpPerHour;
	}

	/**
	 * Update XP from a StatChanged event. Sets startXp on first call.
	 */
	void updateXp(int currentXp)
	{
		if (startXp == -1)
		{
			startXp = currentXp;
		}
		lastXp = currentXp;
	}
}

package com.firemaking;

import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.AnimationID;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayMenuEntry;

@Slf4j
@PluginDescriptor(
	name = "Firemaking",
	description = "Tracks firemaking session stats including fires lit, XP gained, and rates",
	tags = {"firemaking", "skilling", "overlay"}
)
public class FiremakingPlugin extends Plugin
{
	private static final String FIRE_MESSAGE = "The fire catches and the logs begin to burn.";
	private static final int FIREMAKING_ANIMATION = AnimationID.FIREMAKING;

	@Inject
	private Client client;

	@Inject
	private FiremakingConfig config;

	@Inject
	private FiremakingOverlay overlay;

	@Inject
	private OverlayManager overlayManager;

	@Getter
	private FiremakingSession session;

	@Getter
	private boolean firemaking;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		session = null;
		firemaking = false;
	}

	@Provides
	FiremakingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FiremakingConfig.class);
	}

	@Subscribe
	public void onOverlayMenuClicked(net.runelite.client.events.OverlayMenuClicked event)
	{
		OverlayMenuEntry entry = event.getEntry();
		if (event.getOverlay() == overlay && entry.getOption().equals(FiremakingOverlay.RESET))
		{
			session = null;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.SPAM && event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		if (event.getMessage().equals(FIRE_MESSAGE))
		{
			if (session == null)
			{
				session = new FiremakingSession();
			}

			session.incrementFiresLit();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.FIREMAKING)
		{
			return;
		}

		if (session != null)
		{
			session.updateXp(event.getXp());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player local = client.getLocalPlayer();
		if (local != null)
		{
			firemaking = local.getAnimation() == FIREMAKING_ANIMATION;
		}

		if (session != null)
		{
			Duration sinceLastActivity = Duration.between(session.getLastActivity(), Instant.now());
			if (sinceLastActivity.compareTo(Duration.ofMinutes(config.statTimeout())) >= 0)
			{
				log.debug("Firemaking session timed out");
				session = null;
			}
		}
	}
}

package com.firemaking;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Units;

@ConfigGroup("firemaking")
public interface FiremakingConfig extends Config
{
	@ConfigItem(
		keyName = "statTimeout",
		name = "Reset stats",
		description = "Duration the session tracker stays active after you stop firemaking",
		position = 1
	)
	@Units(Units.MINUTES)
	default int statTimeout()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "showFiremakingStats",
		name = "Show stats overlay",
		description = "Show the firemaking session stats overlay",
		position = 2
	)
	default boolean showFiremakingStats()
	{
		return true;
	}
}
